	u.User = nil
	nonCredentialedURL := u.String()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, credentialedURL, nil)
	if err != nil {
		return false, err
	}

	credentialedRes, err := client.Do(req)
	if err != nil {
		return false, err
	}
